CONTROL_HEADER = 16


def message_type(message: bytes) -> int | None:
    if len(message) < CONTROL_HEADER:
        return None
    return message[11]


def transaction_id(message: bytes) -> int:
    return message[12] if len(message) > 12 else 0


def elements(message: bytes) -> list[tuple[int, bytes]]:
    out: list[tuple[int, bytes]] = []
    off = CONTROL_HEADER
    while off + 4 <= len(message):
        etype = int.from_bytes(message[off : off + 2], "big")
        elen = int.from_bytes(message[off + 2 : off + 4], "big")
        if off + 4 + elen > len(message):
            break
        out.append((etype, message[off + 4 : off + 4 + elen]))
        off += 4 + elen
    return out


VENDOR_ELEMENT = 0x0025
VENDOR_ID = bytes.fromhex("12345678")


def vendor_payloads(message: bytes):
    for etype, value in elements(message):
        if etype != VENDOR_ELEMENT or len(value) < 10 or value[:4] != VENDOR_ID:
            continue
        size = int.from_bytes(value[8:10], "big")
        if len(value) >= 10 + size:
            yield int.from_bytes(value[6:8], "big"), value[10 : 10 + size]


def retag(template: bytes, txid: int) -> bytes:
    body = bytearray(template)
    body[12] = txid & 0xFF
    return bytes(body)


def reset_request(txid: int) -> bytes:
    return build(RESET_REQUEST, txid, b"")


FACTORY_RESET_PAYLOAD = bytes.fromhex("0000000000000023000400000003")


def factory_reset_request(txid: int) -> bytes:
    return build(RESET_REQUEST, txid, struct.pack(">HH", 37, len(FACTORY_RESET_PAYLOAD)) + FACTORY_RESET_PAYLOAD)


LED_OP_PAYLOAD = 0x39


def led_write_message(txid: int, on: bool) -> bytes:
    value = struct.pack(">IHHH", 0, 0, LED_OP_PAYLOAD, 4) + struct.pack(">I", 1 if on else 0)
    return build(CONFIG_UPDATE_REQUEST, txid, struct.pack(">HH", 37, len(value)) + value)


def build(message_type_value: int, txid: int, payload: bytes) -> bytes:
    header = bytearray(CONTROL_HEADER)
    header[0] = 0x00
    header[1] = 0x10
    header[2] = 0x43
    header[3] = 0x00
    header[11] = message_type_value & 0xFF
    header[12] = txid & 0xFF
    header[13:15] = (len(payload) + 3).to_bytes(2, "big")
    return bytes(header) + payload

